import * as THREE from 'three/webgpu';
import { MeshPhysicalNodeMaterial, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-stat-tile';
  group.position.set(0, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  // Fallback machined card in case GLB loading is slow/unavailable — replaced on load
  const cardGeo = new THREE.BoxGeometry(1.4, 0.9, 0.08);
  const cardMat = new MeshPhysicalNodeMaterial();
  cardMat.colorNode = color(colors.surface);
  cardMat.metalness = 0.5;
  cardMat.roughness = 0.55;
  cardMat.clearcoat = 0.2;
  cardMat.clearcoatRoughness = 0.3;
  const fallbackMesh = new THREE.Mesh(cardGeo, cardMat);
  group.add(fallbackMesh);

  // Accent rim light
  const rimLight = new THREE.PointLight(colors.accent, 1.2, 4);
  rimLight.position.set(0.6, 0.4, 0.8);
  group.add(rimLight);

  let gearMesh = null;
  const meshUrl = '/prism-mock/orrery/meshes/gear-a.glb';

  try {
    const gltf = ctx.glbLoader.load(meshUrl);
    if (gltf && gltf.scene) {
      gearMesh = gltf.scene;
      gearMesh.traverse((child) => {
        if (child.isMesh && child.material) {
          if ('metalness' in child.material) {
            child.material.metalness = Math.min(child.material.metalness ?? 0.5, 0.55);
          }
          if ('roughness' in child.material) {
            child.material.roughness = Math.max(child.material.roughness ?? 0.5, 0.5);
          }
          if ('clearcoat' in child.material) {
            child.material.clearcoat = Math.min(child.material.clearcoat ?? 0.2, 0.25);
          }
        }
      });
      group.remove(fallbackMesh);
      group.add(gearMesh);
    }
  } catch (e) {
    // keep fallback mesh
  }

  const targetMesh = gearMesh || fallbackMesh;

  // Apply cinematic primitives
  const timelines = [];

  const parallaxHandle = ctx.primitives['parallax-scroll'](targetMesh, { intensity: 0.4 });
  if (parallaxHandle && parallaxHandle.timeline) timelines.push(parallaxHandle.timeline);

  const magneticHandle = ctx.primitives['magnetic-cursor'](targetMesh, { radius: 1.2, strength: 0.35 });
  if (magneticHandle && magneticHandle.timeline) timelines.push(magneticHandle.timeline);

  // Weighted-settle entrance
  const settleTl = gsap.timeline();
  settleTl.fromTo(
    targetMesh.scale,
    { x: 0.001, y: 0.001, z: 0.001 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.6, ease: 'power4.out' }
  ).to(targetMesh.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power4.out' });
  timelines.push(settleTl);

  // Hover: rise-in effect
  let hoverTl = null;
  const baseY = targetMesh.position.y;

  const onHoverEnter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(targetMesh.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTl);
  };

  const onHoverLeave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(targetMesh.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTl);
  };

  const onClick = () => {
    if (ctx.emit) {
      ctx.emit('hub-collection.select', { itemId: 'hub-collection-stat-tile' });
    }
  };

  group.userData.handlers = {
    hoverEnter: onHoverEnter,
    hoverLeave: onHoverLeave,
    click: onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill && tl.kill());
    if (hoverTl) hoverTl.kill();
    if (parallaxHandle && parallaxHandle.dispose) parallaxHandle.dispose();
    if (magneticHandle && magneticHandle.dispose) magneticHandle.dispose();

    cardGeo.dispose();
    cardMat.dispose();
    rimLight.dispose && rimLight.dispose();

    if (gearMesh) {
      gearMesh.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
  };

  return group;
}
